import React, { useState, useEffect } from 'react';

function App() {
    const [message, setMessage] = useState('در حال اتصال به سرور...');
    const [status, setStatus] = useState('loading');
    const [apiData, setApiData] = useState(null);

    useEffect(() => {
        fetch('http://localhost:8000/api/test/')
            .then(response => {
                if (!response.ok) {
                    throw new Error('خطا در پاسخ سرور');
                }
                return response.json();
            })
            .then(data => {
                setMessage('✅ بک‌اند در دسترس است!');
                setStatus('success');
                setApiData(data);
                console.log('داده دریافتی:', data);
            })
            .catch(error => {
                setMessage('❌ اتصال به بک‌اند برقرار نشد!');
                setStatus('error');
                console.error('Error:', error);
            });
    }, []);

    return (
        <div style={{ 
            textAlign: 'center', 
            marginTop: '50px',
            fontFamily: 'Segoe UI, Tahoma, Geneva, Verdana, sans-serif'
        }}>
            <h1 style={{ fontSize: '2.5rem', color: '#1976d2' }}>
                🚀 سیستم مدیریت ایمنی
            </h1>
            
            <div style={{
                marginTop: '30px',
                padding: '20px',
                backgroundColor: status === 'success' ? '#d4edda' : status === 'error' ? '#f8d7da' : '#fff3cd',
                borderRadius: '8px',
                maxWidth: '500px',
                marginLeft: 'auto',
                marginRight: 'auto',
                border: '1px solid ' + (status === 'success' ? '#c3e6cb' : status === 'error' ? '#f5c6cb' : '#ffeeba')
            }}>
                <h3 style={{ margin: 0 }}>
                    {message}
                </h3>
                {apiData && (
                    <p style={{ marginTop: '10px', color: '#155724' }}>
                        📩 پاسخ از سرور: {apiData.message}
                    </p>
                )}
            </div>

            <div style={{ marginTop: '40px' }}>
                <p style={{ color: '#666' }}>
                    📋 برای مشاهده پنل ادمین: <br/>
                    <a href="http://localhost:8000/admin" style={{ color: '#1976d2' }}>
                        http://localhost:8000/admin
                    </a>
                </p>
                <p style={{ color: '#666', fontSize: '14px' }}>
                    🔑 کاربر: admin / رمز: 123456
                </p>
            </div>
        </div>
    );
}

export default App;
